//! The brand this build carries — `PROXIMOS_BRAND`, default `proximos` (plan/portal/branding.md).
//!
//! Every constant comes from `portal/branding/<brand>/brand.toml` and its files, generated by
//! build.rs: [`ID`], [`PRODUCT`], [`HUB`], [`NODE`], [`BEACON`], [`MONITOR`], [`MOBILE_APP`],
//! [`HOSTNAME_PREFIX`], [`BLE_ALIAS_PREFIX`], [`CERT_ORGANISATION`], [`SUPPORT_URL`],
//! [`SUPPORT_EMAIL`], [`THEME`], [`LOGO_WIDTH`], [`LOGO_HEIGHT`], [`DOCS_PDF_EN`],
//! [`DOCS_PDF_CS`], [`HOSTNAME_PATTERN`], [`LOGO_SVG`],
//! [`FAVICON_ICO`], [`SPLASH`] and [`I18N_OVERRIDES`].

use std::borrow::Cow;

include!(concat!(env!("OUT_DIR"), "/brand.rs"));

/// The placeholders [`expand`] fills, in the i18n catalogue and the documentation JSON.
///
/// None of them may be a run-time interpolation name of the catalogue (`{device}`, `{client}`
/// …): those are filled per render, these once per build. The portal's i18n tests check that no
/// catalogue string uses one of these names for anything else.
pub const PLACEHOLDERS: [(&str, &str); 5] = [
    ("{brand}", PRODUCT),
    ("{brand_id}", ID),
    ("{mobile_app}", MOBILE_APP),
    ("{hostname_prefix}", HOSTNAME_PREFIX),
    ("{support_email}", SUPPORT_EMAIL),
];

/// `text` with every [`PLACEHOLDERS`] name replaced by this brand's value. Borrowed when there
/// is nothing to replace, which is most strings.
pub fn expand(text: &str) -> Cow<'_, str> {
    if !PLACEHOLDERS.iter().any(|(k, _)| text.contains(k)) {
        return Cow::Borrowed(text);
    }
    let mut out = text.to_string();
    for (k, v) in PLACEHOLDERS {
        if out.contains(k) {
            out = out.replace(k, v);
        }
    }
    Cow::Owned(out)
}

/// decision #17's prefix, which every Hub image names its units with.
pub const DEFAULT_HOSTNAME_PREFIX: &str = "proximos-";

/// The prefixes a Hub hostname may carry in this build: decision #17's `proximos-`, and the
/// brand's own when it is another (plan/portal/branding.md §5). The default build accepts
/// exactly what it did before the brand switch.
pub fn hostname_prefixes() -> &'static [&'static str] {
    if HOSTNAME_PREFIX == DEFAULT_HOSTNAME_PREFIX {
        &[DEFAULT_HOSTNAME_PREFIX]
    } else {
        &[HOSTNAME_PREFIX, DEFAULT_HOSTNAME_PREFIX]
    }
}

/// The eight-hex serial of a Hub hostname, `<prefix><serial8>` for one of
/// [`hostname_prefixes`] (decision #17), or `None`. Expects the hostname lowercased.
pub fn hostname_serial(hostname: &str) -> Option<&str> {
    hostname_prefixes()
        .iter()
        .find_map(|p| hostname.strip_prefix(p))
        .filter(|s| s.len() == 8 && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')))
}

#[cfg(test)]
#[path = "parse.rs"]
#[allow(dead_code)] // build.rs uses the rest; the tests use what they check
mod parse;

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn branding() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../branding")
    }

    fn brands() -> Vec<PathBuf> {
        let mut v: Vec<_> = std::fs::read_dir(branding())
            .unwrap()
            .filter_map(Result::ok)
            .map(|e| e.path())
            .filter(|p| p.join("brand.toml").is_file())
            .collect();
        v.sort();
        v
    }

    #[test]
    fn both_brands_exist() {
        let names: Vec<String> = brands()
            .iter()
            .map(|p| p.file_name().unwrap().to_string_lossy().into_owned())
            .collect();
        assert!(names.contains(&"proximos".to_string()), "{names:?}");
        assert!(names.contains(&"fiber".to_string()), "{names:?}");
    }

    /// brand.env is what the boot scripts read; it is committed, so it can drift from
    /// brand.toml unless something compares them.
    #[test]
    fn every_brand_env_matches_its_brand_toml() {
        for dir in brands() {
            let toml = parse::brand_toml(&std::fs::read_to_string(dir.join("brand.toml")).unwrap())
                .unwrap();
            let env =
                parse::brand_env(&std::fs::read_to_string(dir.join("brand.env")).unwrap()).unwrap();
            assert_eq!(env, parse::expected_env(&toml), "{}", dir.display());
        }
    }

    #[test]
    fn every_brand_has_its_files() {
        for dir in brands() {
            for f in ["logo.svg", "favicon.ico", "splash.pbm"] {
                assert!(dir.join(f).is_file(), "{}/{f}", dir.display());
            }
            let pbm = std::fs::read_to_string(dir.join("splash.pbm")).unwrap();
            parse::pbm(&pbm, 128, 64).unwrap();
        }
    }

    #[test]
    fn the_default_brand_is_proximos_with_todays_values() {
        if ID != "proximos" {
            return;
        }
        assert_eq!(PRODUCT, "ProXimos");
        assert_eq!(HOSTNAME_PREFIX, "proximos-");
        assert_eq!(CERT_ORGANISATION, "ProXimos");
        assert_eq!(THEME, "proximos");
        assert_eq!(
            HOSTNAME_PATTERN,
            "[Pp][Rr][Oo][Xx][Ii][Mm][Oo][Ss]-[0-9A-Fa-f]{8}"
        );
        assert_eq!(DOCS_PDF_EN, Some("PROXIMOS-documentation.pdf"));
    }

    #[test]
    fn the_logo_and_favicon_are_files_not_lfs_pointers() {
        assert!(LOGO_SVG.starts_with(b"<"), "logo.svg is SVG");
        // ICO: reserved 0, type 1.
        assert_eq!(&FAVICON_ICO[..4], &[0, 0, 1, 0]);
    }

    #[test]
    fn the_splash_is_not_blank() {
        let lit: usize = SPLASH
            .iter()
            .map(|r| r.iter().filter(|p| **p == 1).count())
            .sum();
        assert!(lit > 200, "{lit} lit pixels");
    }

    #[test]
    fn expand_fills_every_placeholder_and_leaves_the_rest() {
        assert_eq!(expand("restart {device}"), "restart {device}");
        assert!(matches!(expand("plain"), Cow::Borrowed(_)));
        let s = expand("{brand} Hub, {mobile_app} app, {hostname_prefix}a1b2c3d4, {brand_id}");
        assert_eq!(
            s,
            format!("{PRODUCT} Hub, {MOBILE_APP} app, {HOSTNAME_PREFIX}a1b2c3d4, {ID}")
        );
    }

    #[test]
    fn a_hostname_of_this_brand_has_a_serial() {
        let p = HOSTNAME_PREFIX;
        assert_eq!(hostname_serial(&format!("{p}1a2b3c4d")), Some("1a2b3c4d"));
        // decision #17's prefix is a Hub hostname in every build; another brand's is one only
        // in that brand's build.
        assert_eq!(hostname_serial("proximos-1a2b3c4d"), Some("1a2b3c4d"));
        let other = if p == "proximos-" { "fiber-" } else { "hub-" };
        for bad in [
            format!("{p}1a2b3c4"),
            format!("{p}1a2b3c4d5"),
            format!("{p}1a2b3c4g"),
            format!("{}1A2B3C4D", p.to_uppercase()),
            format!("{other}1a2b3c4d"),
            "hub-1a2b3c4d".to_string(),
        ] {
            assert_eq!(hostname_serial(&bad), None, "{bad}");
        }
    }

    #[test]
    fn the_parser_refuses_what_it_should() {
        let good = std::fs::read_to_string(branding().join("proximos/brand.toml")).unwrap();
        assert!(parse::brand_toml(&good).is_ok());
        assert!(parse::brand_toml(&good.replace("id = \"proximos\"\n", "")).is_err());
        assert!(parse::brand_toml(&format!("{good}\nextra = \"x\"\n")).is_err());
        assert!(parse::brand_toml(&good.replace(
            "ble_alias_prefix = \"proximos-\"",
            "ble_alias_prefix = \"other-\""
        ))
        .is_err());
        assert!(parse::brand_toml(&good.replace("\"ProXimos Hub\"", "\"Pro'Ximos\"")).is_err());
        assert!(parse::pbm("P1\n2 2\n0 1 1", 2, 2).is_err());
        assert!(parse::pbm("P1\n3 1\n010", 2, 2).is_err());
        assert_eq!(
            parse::pbm("P1\n2 2\n0 1\n1 0", 2, 2).unwrap(),
            vec![vec![0, 1], vec![1, 0]]
        );
    }
}
